  g_content = g_pages[page];
  g_device_binding_counts[page] = 0;
  memset(g_device_bindings[page], 0, sizeof(g_device_bindings[page]));
  memset(g_scene_bindings[page], 0, sizeof(g_scene_bindings[page]));

  if (page == 0)
